// sprites.h - tiny cached loader for the pixel-art sprites generated by tools/comfy.
// Paths are relative to the assets dir (e.g. "sprites/void/grunt.png"); textures load
// lazily on first draw (after InitWindow) and keep raylib's POINT filter so the
// BLK NX64 pixel grid stays crisp at any scale.
#ifndef ANGERBLAST_SPRITES_H
#define ANGERBLAST_SPRITES_H

#include <stdbool.h>
#include "raylib.h"

// cached lookup; NULL when the file is missing (callers fall back to geometry)
const Texture2D *sprite_get(const char *path);

// draw centred at `center`, snapped to the nearest integer scale that fits
// `diameter` (<=0 means native 1:1), rotated by `rotation` degrees, tinted.
// Returns false (drawing nothing) when the sprite is unavailable.
bool sprite_draw(const char *path, Vector2 center, float diameter, float rotation, Color tint);

// player-ship lean: whole-pixel row shear by `bank` in [-1,1] (nose toward the
// turn). Native scale only.
bool sprite_draw_banked(const char *path, Vector2 center, float bank, Color tint);

void sprites_unload(void);

#endif // ANGERBLAST_SPRITES_H
